import { Component, computed, effect, inject, input, output, signal, untracked } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { FigurePipe } from '../../core/figure.pipe';
import { Session } from '../../core/session';
import { money } from '../claims/claims-api';
import { PCT_PATTERN, Rate, RatePreview, RatesApi, importRatesError, pctOn, rateError } from './rates-api';

// The rate in force on the sheet's today for each grade, every rate the sheet has for each grade by
// from-date, the form that sets a grade's rate from a date, optionally through a date, an import box
// that sets a rate per pasted line, and a preview of what a candidate rate for a grade would change
// (nothing is saved), and a calendar of each grade's rate on the first of each month of the sheet's
// today's year.
@Component({
  selector: 'app-rates',
  imports: [FigurePipe, ReactiveFormsModule],
  template: `
    <section aria-labelledby="rates-heading">
      <h2 id="rates-heading">Rates</h2>
      <form [formGroup]="form" (ngSubmit)="submit()" aria-label="Set rate">
        <label for="rate-form-grade">Grade</label>
        <select id="rate-form-grade" data-testid="rate-form-grade" formControlName="grade">
          @for (g of grades(); track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-form-pct">Rate (%)</label>
        <input id="rate-form-pct" data-testid="rate-form-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <label for="rate-form-from">From (blank: always)</label>
        <input id="rate-form-from" type="date" data-testid="rate-form-from" formControlName="from" />
        <label for="rate-form-to">To (blank: for good)</label>
        <input id="rate-form-to" type="date" data-testid="rate-form-to" formControlName="to" />
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        @if (error(); as err) {
          <p role="alert" data-testid="rate-form-error">{{ err }}</p>
        }
      </form>
      <form [formGroup]="importForm" (ngSubmit)="importRates()" aria-label="Import rates">
        <label for="import-rates">Import rates (grade,rate,from,to per line)</label>
        <textarea id="import-rates" data-testid="import-rates" formControlName="text" rows="4"></textarea>
        <button type="submit" data-testid="import-rates-submit">Import rates</button>
        @if (imported() !== null) {
          <p role="status">Set <strong data-testid="import-rates-set">{{ imported() }}</strong></p>
        }
        @if (importErr(); as err) {
          <p role="alert" data-testid="import-rates-error">{{ err }}</p>
        }
      </form>
      <form [formGroup]="previewForm" (ngSubmit)="runPreview()" aria-label="Preview rate">
        <label for="rate-preview-grade">Grade</label>
        <select id="rate-preview-grade" data-testid="rate-preview-grade" formControlName="grade">
          @for (g of grades(); track g) {
            <option [value]="g">{{ g }}</option>
          }
        </select>
        <label for="rate-preview-pct">Candidate rate (%)</label>
        <input id="rate-preview-pct" data-testid="rate-preview-pct" formControlName="pct" inputmode="decimal" autocomplete="off" />
        <button type="submit" data-testid="rate-preview">Preview</button>
        @if (previewError(); as err) {
          <p role="alert" data-testid="rate-preview-error">{{ err }}</p>
        }
        @if (previewed(); as r) {
          <p aria-live="polite">
            Claims changed: <span data-testid="rate-preview-count">{{ r.count }}</span>,
            difference: <span data-testid="rate-preview-diff">{{ money(r.cents) | figure }}</span>
          </p>
        }
      </form>
      <table data-testid="rates-current">
        <caption>In force today</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">Rate (%)</th><th scope="col">Versions</th></tr>
        </thead>
        <tbody>
          @for (g of grades(); track g) {
            <tr>
              <th scope="row">{{ g }}</th>
              <td [attr.data-testid]="'rate-current-' + g">{{ (currentOf(g) ?? 'n/a') | figure }}</td>
            </tr>
          }
        </tbody>
      </table>
      @if (calendar(); as cal) {
        <table data-testid="rates-calendar">
          <caption>Rate on the first of each month of {{ cal.year }}</caption>
          <thead>
            <tr>
              <th scope="col">Grade</th>
              @for (m of cal.months; track m) {
                <th scope="col">{{ m }}</th>
              }
            </tr>
          </thead>
          <tbody>
            @for (g of grades(); track g) {
              <tr>
                <th scope="row">{{ g }}</th>
                @for (m of cal.months; track m) {
                  <td [attr.data-testid]="'rate-month-' + g + '-' + m">{{ (monthOf(g, m) ?? 'n/a') | figure }}</td>
                }
              </tr>
            }
          </tbody>
        </table>
      }
      <table data-testid="rates-list">
        <caption>All rates</caption>
        <thead>
          <tr><th scope="col">Grade</th><th scope="col">From</th><th scope="col">To</th><th scope="col">Rate (%)</th><th scope="col">Versions</th></tr>
        </thead>
        <tbody>
          @for (r of sorted(); track r.grade + '-' + (r.from ?? 'start')) {
            <tr [attr.data-testid]="'rate-row-' + r.grade + '-' + (r.from ?? 'start')">
              <th scope="row" data-testid="rate-grade">{{ r.grade }}</th>
              <td data-testid="rate-from">{{ r.from ?? '' }}</td>
              <td data-testid="rate-to">{{ r.to ?? '' }}</td>
              <td data-testid="rate-pct">{{ r.pct | figure }}</td>
              <td data-testid="rate-version">{{ r.version ?? 1 }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Rates {
  private readonly session = inject(Session);
  private readonly api = inject(RatesApi);

  /** The sheet's rates, each for a grade from a from-date. */
  readonly rates = input.required<Rate[]>();
  /** The rates in force on the sheet, with those it inherits from its parent sheets. */
  readonly effective = input.required<Rate[]>();
  /** The rates by grade, then from-date (an undated rate first). */
  protected readonly sorted = computed(() => [...this.rates()].sort((a, b) =>
    a.grade.localeCompare(b.grade) || (a.from ?? '').localeCompare(b.from ?? '')));
  /** A rate just set, for the sheet to take in. */
  readonly saved = output<Rate>();

  protected readonly grades = this.session.grades;
  protected readonly error = signal<string | null>(null);
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private submitting = false;

  protected readonly form = new FormGroup({
    grade: new FormControl<string>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });

  /** The import box: lines of grade,rate,from,to, each a rate as the form sets it. */
  protected readonly importForm = new FormGroup({
    text: new FormControl('', { nonNullable: true }),
  });
  /** How many rates the last import set; null while one runs or before the first. */
  protected readonly imported = signal<number | null>(null);
  protected readonly importErr = signal<string | null>(null);
  private importing = false;

  /** What a candidate percent for a grade would change on the sheet as it is shown. */
  readonly preview = input.required<(grade: string, pct: string) => RatePreview>();
  protected readonly previewed = signal<RatePreview | null>(null);
  protected readonly previewError = signal<string | null>(null);
  protected readonly money = money;

  protected readonly previewForm = new FormGroup({
    grade: new FormControl<string>('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(null));
    // a preview is of the candidate it was run for; once the form changes it is gone
    this.previewForm.valueChanges.subscribe(() => {
      this.previewError.set(null);
      this.previewed.set(null);
    });
    this.importForm.valueChanges.subscribe(() => this.importErr.set(null));
    // a sheet (re)loaded starts with an empty import box
    effect(() => {
      this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.importForm.reset({ text: '' }, { emitEvent: false });
        this.imported.set(null);
        this.importErr.set(null);
      });
    });
    // a preview is of the sheet as it was; once its rates are (re)loaded or changed it is gone
    effect(() => {
      this.rates();
      this.previewed.set(null);
    });
  }

  protected runPreview(): void {
    this.previewed.set(null);
    this.previewError.set(null);
    const { grade, pct } = this.previewForm.getRawValue();
    if (!this.session.grades().includes(grade)) {
      this.previewError.set('Choose a grade.');
      return;
    }
    const value = pct.trim();
    if (!PCT_PATTERN.test(value)) {
      this.previewError.set('Enter a percent of 0.00 or more with up to two decimals.');
      return;
    }
    this.previewed.set(this.preview()(grade, (Number(value)).toFixed(2)));
  }

  /** The grade's rate in force on the sheet's today, or null when it has none then. */
  protected currentOf(grade: string): string | null {
    return pctOn(this.effective().filter((r) => r.grade === grade), this.session.today());
  }

  /** The months (yyyy-mm) of the sheet's today's calendar year; null before the sheet has a today. */
  protected readonly calendar = computed(() => {
    const year = this.session.today()?.slice(0, 4);
    if (!year) return null;
    return { year, months: Array.from({ length: 12 }, (_, i) => `${year}-${String(i + 1).padStart(2, '0')}`) };
  });

  /** The grade's rate in force on the first day of a month (yyyy-mm), or null when it has none then. */
  protected monthOf(grade: string, month: string): string | null {
    return pctOn(this.effective().filter((r) => r.grade === grade), `${month}-01`);
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const { grade, pct, from, to } = this.form.getRawValue();
    if (!this.session.grades().includes(grade)) {
      this.error.set('Choose a grade.');
      return;
    }
    const value = pct.trim();
    if (!PCT_PATTERN.test(value)) {
      this.error.set('Enter a percent of 0.00 or more with up to two decimals.');
      return;
    }
    const fromDate = from.trim();
    if (fromDate !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(fromDate)) {
      this.error.set('Enter a from-date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    const toDate = to.trim();
    if (toDate !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(toDate)) {
      this.error.set('Enter a to-date as yyyy-mm-dd, or leave it blank.');
      return;
    }
    if (fromDate !== '' && toDate !== '' && toDate < fromDate) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    this.submitting = true;
    try {
      const rate = await this.api.set(sheetId, grade, value, fromDate || null, toDate || null);
      if (this.session.sheetId() === sheetId) this.saved.emit(rate);
      this.form.reset({ grade, pct: '', from: '', to: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(rateError(e));
    } finally {
      this.submitting = false;
    }
  }

  /** Set a rate per imported line, all or none; then show how many were set. */
  protected async importRates(): Promise<void> {
    if (this.importing) return;
    this.imported.set(null);
    this.importErr.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const text = this.importForm.getRawValue().text;
    if (!text.trim()) {
      this.importErr.set('Paste at least one line of grade,rate,from,to.');
      return;
    }
    this.importing = true;
    try {
      const rates = await this.api.importRates(sheetId, text);
      if (this.session.sheetId() !== sheetId) return;
      rates.forEach((r) => this.saved.emit(r));
      this.importForm.reset({ text: '' }, { emitEvent: false });
      this.imported.set(rates.length);
    } catch (e) {
      this.importErr.set(importRatesError(e));
    } finally {
      this.importing = false;
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import { Claim, cents, isBound, isCorrection, lateFrom, overdue, plusDays } from '../claims/claims-api';

export { plusDays };

/** A percent of 0.00 or more with up to two decimals. */
export const PCT_PATTERN = /^\d{1,7}(\.\d{1,2})?$/;

export interface Rate {
  grade: string;
  /** The first date (yyyy-mm-dd) the rate is in force; null when it applies from the beginning of time. */
  from: string | null;
  /** The last date (yyyy-mm-dd) the rate applies; null when it applies for good. */
  to: string | null;
  /** Always with two decimals, as the server formats it. */
  pct: string;
  /** How many versions the rate has, the one shown (its newest) being in force; absent on a rate
   *  worked out on the screen rather than read from the server. */
  version?: number;
  /** For a forward-only newest version (saved with a from-date on or after the sheet's today then),
   *  the highest claim id there was when it was saved: only claims added after it apply it; null or
   *  absent when it applies to every claim. */
  afterClaim?: number | null;
  /** The versions a claim added before the newest one applies instead, newest first. */
  earlier?: EarlierRate[];
}

/** An earlier version of a rate as a claim added before its later forward-only one applies it. */
export interface EarlierRate {
  pct: string;
  to: string | null;
  afterClaim: number | null;
}

/** Of rates, each as it applies to a claim added as `added` (its own id, or for a copy in a clone
 *  the claim it copies was added as): a forward-only version saved after it was added gives way to
 *  the newest earlier one that applies to it; a rate none of whose versions does is left out. */
export function ratesForClaim(rates: readonly Rate[], added: number): Rate[] {
  const out: Rate[] = [];
  for (const r of rates) {
    if (r.afterClaim == null || added > r.afterClaim) {
      out.push(r);
      continue;
    }
    const e = (r.earlier ?? []).find((v) => v.afterClaim === null || added > v.afterClaim);
    if (e) out.push({ grade: r.grade, from: r.from, to: e.to, pct: e.pct, version: r.version });
  }
  return out;
}

/** A sheet's own rates and those of each of its ancestors (its parent's first): `inForce` the rates
 *  in force on it as one list, as the rates panel shows them, and `forClaim` the ones a claim
 *  applies, leaving out the forward-only versions saved after it was added. */
export class RateLevels {
  readonly inForce: Rate[];
  /** Every forward-only mark the rates have, lowest first. */
  private readonly marks: number[];
  /** The rates claims apply, by how many of the marks they were added after. */
  private readonly byMark = new Map<number, Rate[]>();

  constructor(private readonly own: readonly Rate[], private readonly inherited: readonly (readonly Rate[])[]) {
    this.inForce = effectiveRates(own, inherited);
    const marks = new Set<number>();
    for (const r of [...own, ...inherited.flat()]) {
      if (r.afterClaim != null) marks.add(r.afterClaim);
      for (const e of r.earlier ?? []) if (e.afterClaim !== null) marks.add(e.afterClaim);
    }
    this.marks = [...marks].sort((a, b) => a - b);
  }

  /** The rates, with what the sheet inherits, as one list, as a claim added as `added` applies them. */
  forClaim(added: number): Rate[] {
    const passed = this.marks.filter((m) => m < added).length;
    if (passed === this.marks.length) return this.inForce;
    let rates = this.byMark.get(passed);
    if (!rates) {
      rates = effectiveRates(ratesForClaim(this.own, added), this.inherited.map((l) => ratesForClaim(l, added)));
      this.byMark.set(passed, rates);
    }
    return rates;
  }
}

/** Of one grade's rates, the one in force on a date (yyyy-mm-dd): the one with the latest from-date
 *  on or before it, an undated rate applying from the beginning of time; null when none applies yet,
 *  or when that one's to-date has passed by then. */
export function pctOn(rates: readonly Rate[], date: string | null): string | null {
  let best: Rate | null = null;
  for (const r of rates) {
    if (r.from !== null && (date === null || r.from > date)) continue;
    if (best === null || (best.from ?? '') < (r.from ?? '')) best = r;
  }
  if (best?.to != null && date !== null && best.to < date) return null;
  return best?.pct ?? null;
}

/** The rates in force on a sheet as one list: for each grade and date, the rate in force then of
 *  the first of the sheet's own rates, then each ancestor's in `inherited` (its parent's first),
 *  that has one. The dates are cut where any of them starts or ends, each piece taking the rate
 *  the levels give it; with nothing inherited it is the sheet's own. */
export function effectiveRates(own: readonly Rate[], inherited: readonly (readonly Rate[])[]): Rate[] {
  if (inherited.every((l) => l.length === 0)) return [...own];
  const levels = [own, ...inherited];
  const grades = [...new Set(levels.flatMap((l) => l.map((r) => r.grade)))].sort();
  const out: Rate[] = [];
  for (const grade of grades) {
    const byLevel = levels.map((l) => l.filter((r) => r.grade === grade));
    const cuts = new Set<string>();
    for (const l of byLevel) {
      for (const r of l) {
        if (r.from !== null) cuts.add(r.from);
        if (r.to !== null) cuts.add(plusDays(r.to, 1));
      }
    }
    const starts: (string | null)[] = [null, ...[...cuts].sort()];
    starts.forEach((start, i) => {
      const next = starts[i + 1] ?? null;
      const end = next === null ? null : plusDays(next, -1);
      const on = start ?? end ?? '1970-01-01';
      for (const l of byLevel) {
        const pct = pctOn(l, on);
        if (pct !== null) {
          out.push({ grade, from: start, to: end, pct });
          break;
        }
      }
    });
  }
  return out;
}

/** What a candidate rate for a grade would change: how many claims' dues, and by how much in cents
 *  (new minus current). */
export interface RatePreview {
  count: number;
  cents: number;
}

// The sheet's rate for each grade, read and written through the server.
@Injectable({ providedIn: 'root' })
export class RatesApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Rate[]> {
    return firstValueFrom(this.http.get<Rate[]>(this.url(sheetId), { headers: this.headers() }));
  }

  /** The rates of each of the sheet's ancestors as they are now, its parent's first. */
  inherited(sheetId: string): Promise<Rate[][]> {
    return firstValueFrom(this.http.get<Rate[][]>(`${this.url(sheetId)}/inherited`, { headers: this.headers() }));
  }

  set(sheetId: string, grade: string, pct: string, from: string | null, to: string | null): Promise<Rate> {
    return firstValueFrom(
      this.http.put<Rate>(`${this.url(sheetId)}/${encodeURIComponent(grade)}`, { pct, from, to }, { headers: this.headers() }),
    );
  }

  /** Set a rate for each pasted line of grade,rate,from,to, all or none; the rates set, in line order. */
  importRates(sheetId: string, text: string): Promise<Rate[]> {
    return firstValueFrom(this.http.post<Rate[]>(`${this.url(sheetId)}/import`, { text }, { headers: this.headers() }));
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/rates`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function rateError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Choose a grade, enter a percent of 0.00 or more with up to two decimals and a from-date and to-date as yyyy-mm-dd or none, the to-date not before the from-date.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'The rate was changed at the same moment; try again.';
  return otherError(e);
}

export function importRatesError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) {
    return 'Paste lines of grade,rate,from,to: a grade A, B or C, a percent of 0.00 or more with up to two decimals, and a from-date and to-date as yyyy-mm-dd or blank, the to-date not before the from-date.';
  }
  if (e instanceof HttpErrorResponse && e.status === 409) return 'A rate was changed at the same moment; try again.';
  return otherError(e);
}

/** Whole cents times a percent (in hundredths of a percent), divided by 100, in whole cents,
 *  rounded half to even, or half up when `halfUp` (a negative product rounded as its size is).
 *  Worked in BigInt so large amounts stay exact. */
export function dueCents(cents: number, pctHundredths: number, halfUp = false): number {
  const product = BigInt(cents) * BigInt(pctHundredths);
  const size = product < 0n ? -product : product;
  const whole = size / 10000n;
  const rest = size % 10000n;
  const rounded = rest > 5000n || (rest === 5000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
  return Number(product < 0n ? -rounded : rounded);
}

/** A holder's part in cents of an unsettled shared claim: its amount times their share (in hundredths
 *  of a percent) over 100, times the rate of the holder's own grade in force on the claim's date (`rates`:
 *  those of that grade) over 100, rounded half up when `halfUp` (the claim's rounding policy) else half
 *  to even; null (a part of 0.00) when that grade has no rate then. */
export function holderPartCents(rates: readonly Rate[], c: Claim, shareHundredths: number, halfUp: boolean): number | null {
  const pct = pctOn(rates, c.date);
  if (pct === null) return null;
  const product = BigInt(cents(c.amount)) * BigInt(shareHundredths) * BigInt(cents(pct));
  const size = product < 0n ? -product : product;
  const whole = size / 100000000n;
  const rest = size % 100000000n;
  const rounded = rest > 50000000n || (rest === 50000000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
  return Number(product < 0n ? -rounded : rounded);
}

/** What a claim's late charge follows: the sheet's today and the late percent in force on each boundary date. */
export interface Lateness {
  today: string | null;
  /** The late percent with two decimals in force on a date. */
  latePctOn: (date: string) => string;
  /** The grace days a claim has (those of its person's grade in force on its date); none when left out. */
  graceOf?: (c: Claim) => number;
}

/** A claim's due in cents: the due fixed when it was settled, else the due a statement bound it to
 *  (late charge included), else the greater of the sheet's floor in force on its date and its figure (its
 *  amount times its grade's rate in force on its date, rounded half up when `halfUp` (the claim's rounding
 *  policy) else half to even), with the late charge worked out on that floored figure, rounded the same way,
 *  on top (a correction is neither raised to the floor nor charged late); null (n/a) with no figure. */
export function claimDueCents(rates: readonly Rate[], c: Claim, floorCents: number, late: Lateness, halfUp: boolean): number | null {
  if (c.settledDue !== null) return cents(c.settledDue);
  if (isBound(c)) return c.statedDue === null ? null : cents(c.statedDue);
  const figure = figureCents(rates, c, halfUp);
  if (figure === null) return null;
  const floored = isCorrection(c) ? figure : Math.max(figure, floorCents);
  return floored + lateChargeCents(c, floored, late, halfUp);
}

function figureCents(rates: readonly Rate[], c: Claim, halfUp: boolean): number | null {
  const pct = pctOn(rates, c.date);
  return pct === null ? null : dueCents(cents(c.amount), cents(pct), halfUp);
}

/** An overdue claim's late charge in cents: for every full 30 days past its due-by plus its grace days, the late percent
 *  in force on that boundary date (that date plus 30, 60, 90 ... days) of its figure plus the charges of the
 *  boundaries before it (compounding), each rounded by
 *  the claim's rounding policy, added up; 0 when it is not overdue or its late charge is waived. */
function lateChargeCents(c: Claim, figure: number, late: Lateness, halfUp: boolean): number {
  const grace = late.graceOf?.(c) ?? 0;
  if (late.today === null || isCorrection(c) || c.waived || !overdue(c, late.today, grace)) return 0;
  const from = lateFrom(c, grace);
  const days = Math.round((Date.parse(late.today) - Date.parse(from)) / 86_400_000);
  let charge = 0;
  for (let step = 1; step <= Math.floor(days / 30); step++) {
    const pct = cents(late.latePctOn(plusDays(from, step * 30)));
    if (pct !== 0) charge += dueCents(figure + charge, pct, halfUp);
  }
  return charge;
}

